module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

reg [3:0] count;
reg [9:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 0;
        sum <= 0;
        valid_out <= 0;
    end else begin
        if (valid_in) begin
            sum <= sum + {data_in, 2'b0};
            count <= count + 1;
            if (count == 4'd4) begin
                valid_out <= 1;
                count <= 0;
            end else begin
                valid_out <= 0;
            end
        end
    end
end

assign data_out = sum;

endmodule
